class Counter {
    public int Value;
    public bool Enabled;
    public int Add(int amount = 1) { Value += amount; return Value; }
    public Counter Self() => this;
}
void Change(Counter value) { value.Value += 10; }
void Main() {
    var a = new Counter(); var b = a;
    Print(a.Value); Print(a.Enabled);
    b.Value = 3; Print(a.Add()); Change(b); Print(a.Value);
    Print(a == b); Print(a == a.Self()); Print(a != new Counter());
}
